/**
 *
 * Tree node types used by DataTable's tree mode. When `treeMode` is enabled,
 * the `data` prop must conform to `TreeNode[]`.
 *
 * [Live Demo](https://www.primereact.org/datatable/)
 *
 * @module useDataTableTree
 * @group headless
 *
 */
/**
 * Represents a single tree node for DataTable's tree mode.
 */
export interface TreeNode {
    /**
     * Unique identifier for the node. Required for expansion and selection tracking.
     */
    key: string;
    /**
     * Row data; column `field` values are resolved from this object.
     */
    data?: Record<string, unknown>;
    /**
     * Child nodes. Presence indicates the node is expandable.
     */
    children?: TreeNode[];
    /**
     * Explicit leaf hint. When `true`, the node is rendered as a leaf even without children.
     */
    leaf?: boolean;
}
